CREATE OR REPLACE FUNCTION public.can_in_channel(_user uuid,_channel uuid,_action text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_any_role(_user,ARRAY['admin','management']::app_role[]) OR (EXISTS(SELECT 1 FROM public.channel_permissions cp JOIN public.user_roles ur ON ur.role=cp.role WHERE cp.channel_id=_channel AND ur.user_id=_user AND public.has_role(_user,ur.role) AND ((_action='view' AND cp.can_view) OR (_action='send' AND cp.can_send) OR (_action='delete' AND cp.can_delete) OR (_action='mention' AND cp.can_mention))) AND COALESCE((SELECT NOT requires_fan_zone OR public.is_fan_zone_member(_user) FROM public.chat_channels WHERE id=_channel),true)) $$;